/* 日语词库 · 给「英语母语、学日语」那一档用的（2026-09-23 加，见 CLAUDE.md「多语言与新手教程」那一节）
   ⚠️ 这个文件是 ja-words/build.py 生成的 —— **别手改**，改 ja-words/g1~g5.txt 然后重跑脚本。
   分档：1~5 = JLPT N5 / N4 / N3 / N2 / N1（五章：石廊 N5 … 墟心 N2，无尽 N3+N2+N1 混出）。
   英文释义是**逐条手写的最常用义**。

   格式：[写法, 英文释义, 类别, 难度, 词性, 读音]   读音是平假名（外来语是片假名）；写法本来就是假名的词读音是 ""
   ⚠️ 跟别的词库一样**共用同一套全局变量**：学日语时下面那段把 WORDS / WMAP / BYCAT / BYPOS / BYLV / ALLW
      整套换成这一份。词对象的 en 是「要学的那个词」（写法），cn 是母语释义（英文），py 是读音（题面挂在词下面、拼写题拼它）。
   ⚠️ **只许往数组末尾追加**（存档码按下标存熟练度）。写法不许重复，同一难度里英文释义不许重复，读音最长 8 个假名。
   ⚠️ 跟中文词库写法一样的词（学生 / 大学…）是允许的：熟练度表 LEX 里日语存成 "ja:词"（game.js 的 lexKey()），不会串。*/
